// Regexes and response from the pinned PyBot cake layer module.
pattern!(A_CAKE, r###"(?i)(?<![a-z])(?:cake|cakes|sponge|gateau|cupcake|cupcakes|victoria sponge|victoria sandwich|madeira|loaf cake|sandwich cake)(?![a-z])"###);
pattern!(BETWEEN, r###"(?i)(?<![a-z])(?:filling|fill|filled|between the layers|between the two|in the middle|the middle of|middle of it|layer|layers|layer it|two layers|three layers|split|split it|sandwich it|halve|in half|what cream|which cream|what jam|cream goes|jam goes|goes between|goes in the middle)(?![a-z])"###);
pattern!(NOT_ASKING, r###"(?i)\b(?:why|sank|sink|sunk|sinking|stodgy|dense|heavy|dry|burn|burnt|undercooked|raw|gummy|domed|dropped|didnt rise|didn't rise|flat|stale|birthday|vegan|gluten|egg free|no eggs|cupcake cases|icing|frosting|whip|whipping|myself|himself|herself|a slice|a piece of|how long|keep|keeps|last|freeze|fridge|calorie|calories|how many|many people|serves|feed|tin size|what size tin|instead of the egg)\b"###);
const NOT_THE_CAKE_ROW: &[&str] = &["amount-in-a-dish", "bakes", "hair-cut-yourself", "half-of-a-number", "plan-followup", "recipe-lemon-drizzle"];
const THE_FILLING: &str = "Jam and buttercream, jam first: a thin layer of jam stops the two halves sliding, then buttercream on top of it - about 3 tablespoons of jam and 150g of buttercream for a 20cm cake. Split the sponge by pushing cocktail sticks in at the height you want all the way round, then cut to them with a long serrated knife, turning the cake as you go so the line meets itself. A chocolate cake takes ganache instead - 100g dark chocolate melted into 100ml double cream, cooled until it holds - and fresh cream with fruit is the best filling there is, though it wants making on the morning you eat it.";
